<?php
 namespace App\Http\Controllers\Merchant; use App\Library\Response; use App\System; use Illuminate\Http\Request; use App\Http\Controllers\Controller; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage; class Card extends Controller { function get(Request $request, $is_export = false, $is_delete = false, $is_restore = false) { $query = $this->authQuery($request, \App\Card::class) ->with(['product' => function ($query) { $query->select(['id', 'name']); }]); $searchType = $request->input('search', false); $searchVal = $request->input('val', false); if ($searchType && $searchVal) { if ($searchType == 'id') { $query->where('id', $searchVal); } else { $query->where($searchType, 'like', '%' . $searchVal . '%'); } } $category_id = (int)$request->input('category_id'); $product_id = $request->input('product_id', -1); if ($category_id > 0) { if ($product_id > 0) $query->where('product_id', $product_id); else { $query->whereHas('product', function ($query) use ($category_id) { $query->where('category_id', $category_id); }); } } $status = $request->input('status'); if (strlen($status)) $query->whereIn('status', explode(',', $status)); $onlyCanSell = (int)$request->input('onlyCanSell'); if ($onlyCanSell) $query->whereRaw('`count_all`>`count_sold`'); $type = $request->input('type'); if (strlen($type)) $query->whereIn('type', explode(',', $type)); $isTrashed = $request->input('trashed') === 'true'; if ($isTrashed) $query->onlyTrashed(); if ($is_delete === true) { if ($isTrashed) { $query->forceDelete(); } else { \App\Card::_trash($query); } return Response::success(); } else if ($isTrashed && $is_restore === true) { \App\Card::_restore($query); return Response::success(); } else { $query->orderByRaw('`product_id`,`type`,`status`,`id`'); if ($is_export === true) { $card_txt = ''; $query->chunk(100, function ($cards) use (&$card_txt) { foreach ($cards as $card) { $card_txt .= $card->card . "\r\n"; } }); $file_name = 'export_cards_' . $this->getUserIdOrFail($request) . '_' . date('YmdHis') . '.txt'; $headers = ['Content-type' => 'text/plain', 'Content-Disposition' => sprintf('attachment; filename="%s"', $file_name), 'Content-Length' => strlen($card_txt)]; return response()->make($card_txt, 200, $headers); } $page = (int)$request->input('current_page', 1); $pageSize = (int)$request->input('per_page', 20); $list = $query->paginate($pageSize, ['*'], 'page', $page); return Response::success($list); } } function export(Request $request) { return self::get($request, true); } function trash(Request $request) { $this->validate($request, [ 'ids' => 'required|string' ]); $ids = $request->post('ids'); $query = $this->authQuery($request, \App\Card::class) ->whereIn('id', explode(',', $ids)); \App\Card::_trash($query); return Response::success(); } function restoreTrashed(Request $request) { $this->validate($request, [ 'ids' => 'required|string' ]); $ids = $request->post('ids'); $query = $this->authQuery($request, \App\Card::class) ->whereIn('id', explode(',', $ids)); \App\Card::_restore($query); return Response::success(); } function deleteTrashed(Request $request) { $this->validate($request, [ 'ids' => 'required|string' ]); $ids = $request->post('ids'); $this->authQuery($request, \App\Card::class) ->whereIn('id', explode(',', $ids)) ->forceDelete(); return Response::success(); } function deleteAll(Request $request) { return $this->get($request, false, true); } function restoreAll(Request $request) { return $this->get($request, false, false, true); } function add(Request $request) { $product_id = (int)$request->post('product_id'); $cards = $request->post('card'); $type = (int)$request->post('type', \App\Card::TYPE_ONETIME); $is_check = $request->post('is_check') === 'true'; $user_id = $this->getUserIdOrFail($request); $product_sql = $this->authQuery($request, \App\Product::class)->where('id', $product_id); $product_sql->firstOrFail(['id']); if ($type === \App\Card::TYPE_REPEAT) { if ($is_check) { if (\App\Card::where('product_id', $product_id)->where('card', $cards)->exists()) { return Response::fail('该卡密已经存在，添加失败'); } } $card = new \App\Card([ 'user_id' => $user_id, 'product_id' => $product_id, 'card' => $cards, 'type' => \App\Card::TYPE_REPEAT, 'count_sold' => 0, 'count_all' => (int)$request->post('count_all', 1) ]); if ($card->count_all < 1 || $card->count_all > 10000000) return Response::forbidden('可售总次数不能超过10000000'); return DB::transaction(function () use ($product_sql, $card) { $card->saveOrFail(); $product = $product_sql->lockForUpdate()->firstOrFail(); $product->count_all += $card->count_all; $product->saveOrFail(); return Response::success(); }); } else { $card_arr = explode("\n", $cards); $card_count = count($card_arr); $per_round = 50000; if ($card_count > $per_round) { return Response::fail('每次添加不能超过 ' . $per_round . ' 张'); } $cards_all = []; if ($is_check) { $cards_tmp = \App\Card::where('user_id', $user_id) ->where('product_id', $product_id) ->get(['card'])->all(); foreach ($cards_tmp as $cards_i) { $cards_all[] = $cards_i['card']; } } $cards_to_insert = []; $card_count_real = 0; for ($i = 0; $i < $card_count; $i++) { $card_number = trim($card_arr[$i]); if (strlen($card_number) < 1) continue; if (strlen($card_number) > 1024) return Response::fail('第 ' . $i . ' 张卡密 ' . $card_number . ' 长度错误<br>卡密最大长度为1024'); if ($is_check) { if (in_array($card_number, $cards_all)) { continue; } $cards_all[] = $card_number; } $cards_to_insert[] = [ 'user_id' => $user_id, 'product_id' => $product_id, 'card' => $card_number, 'type' => \App\Card::TYPE_ONETIME ]; $card_count_real++; } if ($card_count_real === 0) return Response::success(); return DB::transaction(function () use ($product_sql, $cards_to_insert, $card_count_real) { \App\Card::insert($cards_to_insert); $product = $product_sql->lockForUpdate()->firstOrFail(); $product->count_all += $card_count_real; $product->saveOrFail(); return Response::success(); }); } } function edit(Request $request) { $id = (int)$request->post('id'); $card = $this->authQuery($request, \App\Card::class)->findOrFail($id); if ($card) { $cardNumber = $request->post('card'); $type = (int)$request->post('type', \App\Card::TYPE_ONETIME); $count_all = (int)$request->post('count_all', 1); return DB::transaction(function () use ($card, $cardNumber, $type, $count_all) { $card = \App\Card::where('id', $card->id)->lockForUpdate()->firstOrFail(); $card->card = $cardNumber; $card->type = $type; if ($card->type === \App\Card::TYPE_REPEAT) { if ($count_all < $card->count_sold) return Response::forbidden('可售总次数不能低于当前已售次数'); if ($count_all < 1 || $count_all > 10000000) return Response::forbidden('可售总次数不能超过10000000'); $card->count_all = $count_all; } else { $card->count_all = 1; } $card->saveOrFail(); $product = $card->product()->lockForUpdate()->firstOrFail(); $product->count_all -= $card->count_all; $product->count_all += $count_all; $product->saveOrFail(); return Response::success(); }); } return Response::success(); } } 